content.text:
# PR new hunks — what changed since the last review concluded

Last reviewed head: f73465354559f1aa6372b5a0db52f95a573f937c
Current head: 5c83e2f5c160dc2aaf989965df045facbe049669

These hunks are the re-review scope, together with their interaction
neighborhood (direct callers/callees of changed symbols). Every line
NOT shown here is frozen: a finding on an unchanged line must show that
these hunks make the problem worse (the interaction test) — otherwise
it is advisory digest only, never a review thread.

--- diff ---

diff --git a/lib/src/agents/cli_agent.dart b/lib/src/agents/cli_agent.dart
index 00453f990..5074ff599 100644
--- a/lib/src/agents/cli_agent.dart
+++ b/lib/src/agents/cli_agent.dart
@@ -364,12 +364,16 @@ class CliAgent {
   /// periodically / per-line / on error. Otherwise the buffered path is used.
   Future<String> _executeCliCommands(String workDir) async {
     bool evalCond(String cond) => _evaluateCliPromptCondition(cond, workDir);
+    final trackerType = propertyReader.getDefaultTracker();
     final finalCommands = const CliCommandBuilder().buildCommands(
       params.cliCommands,
       params.cliPrompt,
       params.flattenCliPrompts(params.cliPrompts, conditionEvaluator: evalCond),
-      params.flattenCliPromptsByTracker(conditionEvaluator: evalCond),
-      trackerType: propertyReader.getDefaultTracker(),
+      params.flattenCliPromptsByTracker(
+        conditionEvaluator: evalCond,
+        trackerType: trackerType,
+      ),
+      trackerType: trackerType,
       workingDirectory: workDir,
     );
     _ensureOutputFolder(workDir);
diff --git a/lib/src/agents/cli_agent_params.dart b/lib/src/agents/cli_agent_params.dart
index cba80fe32..1a3dc6432 100644
--- a/lib/src/agents/cli_agent_params.dart
+++ b/lib/src/agents/cli_agent_params.dart
@@ -176,22 +176,30 @@ class CliAgentParams {

   /// Flattens `cliPromptsByTracker` using an optional [conditionEvaluator] for
   /// sections that declare a `condition` script path.
+  ///
+  /// When [trackerType] is supplied (or defaults to `'ado'` when blank,
+  /// matching `CliCommandBuilder.resolveCliPrompts` and Java parity),
+  /// condition evaluation runs only for the effective tracker's entry so
+  /// unused tracker condition scripts do not execute.
   Map<String, List<String>>? flattenCliPromptsByTracker({
     bool Function(String condition)? conditionEvaluator,
+    String? trackerType,
   }) {
     final raw = cliPromptsByTrackerRaw;
-    if (raw != null) {
-      final result = <String, List<String>>{};
-      for (final entry in raw.entries) {
-        result[entry.key] = _flattenCliPrompts(
-              entry.value,
-              conditionEvaluator: conditionEvaluator,
-            ) ??
-            const <String>[];
-      }
-      return result;
+    if (raw == null) return cliPromptsByTracker;
+    final effectiveTracker = (trackerType == null || trackerType.trim().isEmpty)
+        ? 'ado'
+        : trackerType;
+    final result = <String, List<String>>{};
+    for (final entry in raw.entries) {
+      final eval = entry.key == effectiveTracker ? conditionEvaluator : null;
+      result[entry.key] = _flattenCliPrompts(
+            entry.value,
+            conditionEvaluator: eval,
+          ) ??
+          const <String>[];
     }
-    return cliPromptsByTracker;
+    return result;
   }

   /// Creates params from a JSON map (the `params` block of a job config).
diff --git a/test/agents/cli_agent_tracker_prompts_test.dart b/test/agents/cli_agent_tracker_prompts_test.dart
index 36b813797..4c714b37c 100644
--- a/test/agents/cli_agent_tracker_prompts_test.dart
+++ b/test/agents/cli_agent_tracker_prompts_test.dart
@@ -77,27 +77,7 @@ void conditionalTrackerPromptsTests() {
             .writeAsStringSync('function action() { return true; }\n');
         File('${tmp.path}/isTracker.js')
             .writeAsStringSync('function action() { return false; }\n');
-        final params = CliAgentParams.fromJson({
-          'cliCommands': ['cat'],
-          'cliPrompts': ['base-rules'],
-          'cliPromptsByTracker': {
-            'jira': [
-              {
-                'id': 'responseFormatJiraWiki',
-                'prompt': 'jira-wiki-comment-format',
-                'condition': '${tmp.path}/isTracker.js',
-              },
-              {
-                'id': 'responseFormatMarkdown',
-                'prompt': 'markdown-output-format',
-                'condition': '${tmp.path}/isScm.js',
-              },
-              'jira-context-rules',
-            ],
-          },
-          'envVariables': {'DEFAULT_TRACKER': 'jira'},
-          'cleanupInputFolder': false,
-        });
+        final params = _buildConditionalTrackerParams(tmp.path);
         expect(params.cliPromptsByTracker?['jira'], [
           'jira-wiki-comment-format',
           'markdown-output-format',
@@ -117,5 +97,50 @@ void conditionalTrackerPromptsTests() {
         await tmp.delete(recursive: true);
       }
     });
+
+    test('evaluates conditions only for effective tracker key', () {
+      final params = _buildConditionalTrackerParams('/tmp');
+      final evaluated = <String>[];
+      final resolved = params.flattenCliPromptsByTracker(
