  final stagedDart = <String>[];
  final stagedLib = <String>[];
  final stagedTests = <String>[];
  final targetTests = <String>{};

  for (final raw in stagedPaths) {
    final p = raw.trim().replaceFirst(RegExp(r'^\./'), '');
